// Improved waypoint follower with full 3D PID, yaw integral, and disturbance compensation.
export default function makeController() {
  let targetIndex = -1, phase = 'climb', settle = 0;
  let ix = 0, iy = 0, iz = 0, iyaw = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  return {
    step(obs) {
      const p = obs.pos, v = obs.vel;
      let target;
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        if (phase === 'align') {
          target = { x: gate.x - 0.45, y: gate.y, z: gate.z };
          // If already past the gate x, need to go back around safely
          if (p.x > gate.x - 0.15 && Math.hypot(p.y - gate.y, p.z - gate.z) < 0.55) {
            target = { x: gate.x - 0.50, y: Math.min(2.4, gate.y + 0.65), z: gate.z };
          }
          const dy = p.y - gate.y, dz = p.z - gate.z;
          const distAlign = Math.hypot(target.x - p.x, dy, dz);
          if (distAlign < 0.12 && Math.hypot(v.x, v.y, v.z) < 0.45 && Math.abs(dy) < 0.12 && Math.abs(dz) < 0.08) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 8) phase = 'cross';
        }
        if (phase === 'cross') {
          const dy = Math.abs(p.y - gate.y), dz = Math.abs(p.z - gate.z);
          // Abort cross if blown off alignment before reaching gate plane
          if (p.x < gate.x - 0.12 && (dy > 0.18 || dz > 0.09)) {
            phase = 'align';
            settle = 0;
            target = { x: gate.x - 0.45, y: gate.y, z: gate.z };
          } else {
            target = { x: gate.x + 0.40, y: gate.y, z: gate.z };
          }
        }
      } else {
        target = { x: obs.pad.centre.x, y: 0.65, z: obs.pad.centre.z };
        const horizErr = Math.hypot(target.x - p.x, target.z - p.z);
        const horizVel = Math.hypot(v.x, v.z);
        if (phase !== 'descend' && horizErr < 0.10 && horizVel < 0.25 && Math.abs(p.y - 0.65) < 0.25) {
          phase = 'descend';
        }
        if (phase === 'descend') {
          if (horizErr > 0.18) {
            target.y = Math.max(p.y, 0.35);
          } else {
            target.y = 0.02;
          }
        }
      }

      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      if (Math.abs(ex) < 0.6) ix = clamp(ix + ex * 0.01, -1.2, 1.2);
      if (Math.abs(ez) < 0.6) iz = clamp(iz + ez * 0.01, -1.2, 1.2);
      iy = clamp(iy + ey * 0.01, -0.8, 2.2);

      // Higher stiffness on z and y when crossing gate
      const crossBoost = (obs.gateIndex < 3 && phase === 'cross') ? 1.4 : 1.0;

      const ax = clamp(4.2 * ex - 3.4 * v.x + 2.2 * ix, -3.5, 3.5);
      const az = clamp((4.5 * crossBoost) * ez - (3.6 * crossBoost) * v.z + 2.4 * iz, -3.8, 3.8);
      const ay = clamp((6.0 * crossBoost) * ey - 3.8 * v.y + 2.8 * iy, -4.0, 5.0);

      const cy = Math.cos(obs.att.yaw), sy = Math.sin(obs.att.yaw);
      const axBody = cy * ax - sy * az;
      const azBody = sy * ax + cy * az;

      const gEff = Math.max(5.0, 9.81 + ay);
      const pitch = clamp(Math.atan2(axBody, gEff), -0.48, 0.48);
      const roll = clamp(Math.atan2(-azBody, gEff), -0.48, 0.48);

      const tiltCos = Math.max(0.65, Math.cos(obs.att.roll) * Math.cos(obs.att.pitch));
      let thrust = (0.725 * (9.81 + ay)) / (16 * tiltCos);
      if (obs.gateIndex === 3 && phase === 'descend' && p.y <= 0.085 && Math.hypot(ex, ez) < 0.12 && Math.hypot(v.x, v.z) < 0.25) {
        // Soft touchdown and hold on pad
        thrust = clamp(thrust * 0.6, 0, 0.35);
      }

      iyaw = clamp(iyaw - obs.att.yaw * 0.01, -0.8, 0.8);
      const yawRate = clamp(-3.5 * obs.att.yaw - 0.3 * obs.rates.yaw + 2.5 * iyaw, -2, 2);

      return {
        thrust: clamp(thrust, 0, 1),
        roll,
        pitch,
        yawRate,
      };
    },
  };
}

