        const errAy = ayMeas - (prevAccCmd.y - 9.81);
        const errAz = azMeas - prevAccCmd.z;

        fastDistX = clamp(fastDistX + 0.12 * (errAx - fastDistX), -6.0, 6.0);
        fastDistY = clamp(fastDistY + 0.10 * (errAy - fastDistY), -4.5, 4.5);
        fastDistZ = clamp(fastDistZ + 0.12 * (errAz - fastDistZ), -6.0, 6.0);
      }
      prevVel = { x: v.x, y: v.y, z: v.z };

      let target;
      let kpX = 4.2, kdX = 3.4;
      let kpZ = 5.0, kdZ = 3.9;
      let kpY = 6.2, kdY = 4.0;

      if (obs.gateIndex < 3) {
